<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePlanStore} from '../stores/plan'
import MapContainer from '../components/MapContainer.vue'
import PoiCardOverlay from '../components/PoiCardOverlay.vue'
import {planningPointers} from '../planning/pointers.mjs'
import {getAuthSession} from '../auth/session.mjs'
import {createPlanningAPI,displayTimeRange} from '../planning/client.mjs'
import {renderPlanningResult} from '../planning/result-ui.mjs'
import {createRevisionExperience} from '../planning/revision-ui.mjs'
import '../planning/ui.css'
import '../planning/formal.css'
const route=useRoute(),router=useRouter(),store=usePlanStore(),api=createPlanningAPI()
const itinerary=ref(null),error=ref(''),loading=ref(true),result=ref(null),workspace=ref(null),activePoi=ref(''),detailPoi=ref(null)
let generation=0,controller,unsubscribe,identity=null
const itineraryPois=computed(()=>[...store.pois,...(itinerary.value?.eventVenues||[]).filter(p=>!store.pois.some(x=>x.poiId===p.poiId))]);
const itinerarySelected=computed(()=>[...new Set([...store.checkedIds,...(itinerary.value?.days||[]).flatMap(d=>d.items.filter(i=>i.type==='fixed_event').map(i=>i.poiId))])]);
const mapPlan=computed(()=>itinerary.value?{days:itinerary.value.days.map((d,i)=>({day:i+1,date:d.date,items:d.items.filter(x=>['visit','fixed_event'].includes(x.type)).map((x,j)=>({...x,order:j+1,duration:x.durationMinutes}))}))}:null)
const h=(tag,attrs={},children=[])=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(v==null||v===false)continue;if(k==='text')n.textContent=v;else if(k.startsWith('on'))n.addEventListener(k.slice(2),v);else n.setAttribute(k,v)}for(const c of children.flat())if(c)n.append(c);return n}
const revisions=createRevisionExperience({getPois:()=>store.pois,onUpdate:async(it,meta)=>{await show(it);if(meta?.reason==='commit'){await nextTick();result.value?.querySelector('.day')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}}})
async function show(it){planningPointers.set(it.context.lineId,it.id);itinerary.value=it;if(store.lineId!==it.context.lineId||!store.line)await store.loadLine(it.context.lineId);store.checkedIds=[...it.context.selectedPoiIds];store.timeRange={...store.timeRange,...it.context.dateRange};loading.value=false;await nextTick();if(!result.value)return;renderPlanningResult({itinerary:it,container:result.value,h,pois:itineraryPois.value,photoEl:p=>h('img',{class:'itinerary-photo',src:(import.meta.env.BASE_URL||'/')+(p.realPhoto||'').replace(/^\//,''),alt:p.name,loading:'lazy'}),onPoi:openPoi,onEdit:()=>router.push(`/customize/${it.context.lineId}`),onHome:()=>router.push('/'),onModify:focusRevision});revisions.mount(workspace.value,it,{timeline:result.value})}
watch(()=>route.params.id,async id=>{const token=++generation;controller?.abort();controller=new AbortController();revisions.unmount();loading.value=true;error.value='';try{const it=await api(`/api/itineraries/${encodeURIComponent(id)}`,undefined,{signal:controller.signal});if(token===generation)await show(it)}catch(e){if(token===generation&&!controller.signal.aborted){loading.value=false;error.value=e.message||'暂时无法读取行程，请返回重新规划。'}}},{immediate:true})
function focusRevision(){workspace.value?.scrollIntoView({behavior:'smooth',block:'center'});workspace.value?.classList.add('revision-highlight');setTimeout(()=>workspace.value?.classList.remove('revision-highlight'),1500);workspace.value?.querySelector('textarea')?.focus({preventScroll:true})}
function openPoi(id){activePoi.value=id;detailPoi.value=store.pois.find(p=>p.poiId===id)||null}
function viewDetail(id){detailPoi.value=null;router.push(`/poi/${id}`)}
function printPlan(){window.print()}
function download(){const it=itinerary.value;if(!it)return;const lines=[store.line?.title||'我的圣地巡礼',...it.days.flatMap(d=>[d.date,...d.items.filter(x=>['visit','meal','rest','travel','fixed_event','event_checkin'].includes(x.type)).map(x=>displayTimeRange(x)+' '+(x.type==='fixed_event'?'游客日程 · '+x.label+' · '+(x.locationName||x.poiId):x.type==='event_checkin'?'提前到场':x.type==='visit'?store.pois.find(p=>p.poiId===x.poiId)?.name||x.poiId:{meal:'用餐',rest:'休息',travel:'交通接驳'}[x.type]))]),...(it.pendingPoiIds?.length?['待安排（未舍弃）：'+it.pendingPoiIds.map(id=>store.pois.find(p=>p.poiId===id)?.name||id).join('、')]:[])];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='圣地巡礼行程.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>{unsubscribe=getAuthSession().subscribe(snapshot=>{if(snapshot.loading)return;const next=snapshot.user?.id||'guest';if(identity!==null&&next!==identity){generation++;controller?.abort();revisions.unmount();planningPointers.clear();itinerary.value=null;store.checkedIds=[];router.push('/')}identity=next})})
onBeforeUnmount(()=>{unsubscribe?.();generation++;controller?.abort();revisions.unmount()})
</script>
<template><div class="page formal-itinerary"><p v-if="loading" role="status">正在读取行程…</p><div v-else-if="error" role="alert"><p>{{error}}</p><button class="btn" @click="router.push('/')">返回首页</button></div><template v-else-if="itinerary"><nav class="itinerary-topbar" aria-label="行程导航"><div class="itinerary-nav-left"><router-link :to="`/customize/${itinerary.context.lineId}`" class="itinerary-back"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg><span>返回规划页</span></router-link><router-link to="/" class="itinerary-home" aria-label="返回首页" title="返回首页"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/></svg></router-link></div><button type="button" class="btn itinerary-sticky-edit" @click="focusRevision">修改这份行程</button></nav><h1>{{store.line?.title}} · {{itinerary.days.length}} 天</h1><div class="itinerary-map"><MapContainer :pois="itineraryPois" :selected-ids="itinerarySelected" :plan="mapPlan" :active-poi-id="activePoi" :interactive="true" @marker-click="openPoi" :city="store.line?.city" :ip-name="store.ip?.name"/></div><PoiCardOverlay v-if="detailPoi" :poi="detailPoi" @close="detailPoi=null" @view-detail="viewDetail"/><div ref="result"/><section id="revision-workspace" ref="workspace" class="panel"/><details class="itinerary-export"><summary>导出行程</summary><button class="revision-text-action" @click="download">下载文字行程</button><button class="revision-text-action" @click="printPlan">打印行程</button></details></template></div></template>
